from taf.gnb.oam.coam.cu.interfaces.cuoam21b import CUOAM21B
from taf.gnb.oam.coam.cu.schemas.internal.asm.security_generic_response import (
    SecurityGenericResponseASMv1,
)
from taf.gnb.oam.coam.cu.schemas.internal.trs.crl_update_status_v1 import (
    CrlUpdateStatusTRSV1,
)
from taf.gnb.oam.coam.cu.schemas.internal.trs.get_trs_operation_status_v1 import (
    OperationStatus,
)
from taf.gnb.oam.coam.cu.schemas.internal.trs_v2.certificates_info_v2 import (
    CertificatesInfoTRSV2,
)
from taf.gnb.oam.coam.cu.services.internal.trs.trs_v2 import TRSv2
from taf.gnb.oam.coam.cu.utilities.base64 import decode_base64_encoded_file
from taf.gnb.oam.coam.cu.utilities.file_operations import copy_file_to_new_location
from taf.gnb.oam.coam.cu.schemas.internal.trs.ip_security_associations import IPSecurityAssociation


class CUOAM22R4(CUOAM21B):
    def __init__(self, con_details):
        super(CUOAM22R4, self).__init__(con_details)
        self.trs_v2 = TRSv2(con_details=con_details)

    def generate_csr_for_ne(self, timeout=30, key_pool_type='RSA', raw=False):
        response = self.trs_v2.generate_csr_for_ne(timeout=timeout, key_pool_type=key_pool_type)
        return response if raw else OperationStatus.from_object_dict(response)

    def get_csr_file(self, path, timeout=30, key_pool_type='RSA'):
        csr_file_path = self.trs_v2.get_csr_file(timeout=timeout, key_pool_type=key_pool_type)
        copy_file_to_new_location(csr_file_path, path)

        return decode_base64_encoded_file(path)

    def install_operators_certificate(self, certificate_file_path, certificate_type, timeout=30, raw=False):
        response = self.trs_v2.install_operators_certificate(certificate_file_path=certificate_file_path,
                                                             certificate_type=certificate_type,
                                                             timeout=timeout)
        return response if raw else OperationStatus.from_object_dict(response)

    def get_operator_certificate_list(self, timeout=30, raw=False):
        response = self.trs_v2.get_operator_certificate_list(timeout=timeout)
        return response if raw else CertificatesInfoTRSV2.from_object_dict(response)

    def delete_all_operator_certificates(self, timeout=30, raw=False):
        response = self.trs_v2.delete_all_operator_certificates(timeout=timeout)
        return response if raw else OperationStatus.from_object_dict(response)

    def get_operator_certificate(self, certificate_id, timeout=30, raw=False):
        response = self.trs_v2.get_operator_certificate(certificate_id=certificate_id, timeout=timeout)
        return response if raw else CertificatesInfoTRSV2.from_object_dict(response)

    def delete_operator_certificate(self, certificate_id, timeout=30, raw=False):
        response = self.trs_v2.delete_operator_certificate(certificate_id=certificate_id, timeout=timeout)
        return response if raw else OperationStatus.from_object_dict(response)

    def trigger_certificate_initialization(self, timeout=30, key_pool_type='RSA', raw=False):
        response = self.trs_v2.trigger_certificate_initialization(timeout=timeout, key_pool_type=key_pool_type)
        return response if raw else OperationStatus.from_object_dict(response)

    def trigger_cmp_server_key_update(self, timeout=30, key_pool_type='RSA', raw=False):
        response = self.trs_v2.trigger_cmp_server_key_update(timeout=timeout, key_pool_type=key_pool_type)
        return response if raw else OperationStatus.from_object_dict(response)

    def update_cmp_server_settings(self, ref_number, psk_key, timeout=30, key_pool_type='RSA', raw=False):
        response = self.trs_v2.update_cmp_server_settings(ref_number=ref_number,
                                                          psk_key=psk_key,
                                                          timeout=timeout,
                                                          key_pool_type=key_pool_type)
        return response if raw else OperationStatus.from_object_dict(response)

    def trigger_crl_information_update(self, timeout=30, raw=False):
        response = self.trs_v2.trigger_crl_information_update(timeout=timeout)
        return response if raw else OperationStatus.from_object_dict(response)

    def get_current_crl(self, timeout=30, raw=False):
        response = self.trs_v2.get_current_crl(timeout=timeout)
        return response if raw else CrlUpdateStatusTRSV1.from_object_dict(response)

    def update_cu_psk_configuration(self, password, timeout=30, raw=False):
        response = self.trs.update_cu_psk_configuration(password=password, timeout=timeout)
        return response if raw else str(response)

    def update_expired_password(self, new_password, curr_username='Nemuadmin', curr_password='nemuuser', timeout=30):
        response = self.asm_v1.update_expired_password(curr_password=curr_password,
                                                       new_password=new_password,
                                                       curr_username=curr_username,
                                                       timeout=timeout)
        return SecurityGenericResponseASMv1.from_object_dict(response)

    def get_ip_security_associations(self, policy_id, tnl_pod_hostname, timeout=30, raw=False):
        response = self.trs.get_ip_security_associations(policy_id=policy_id,
                                                         tnl_pod_hostname=tnl_pod_hostname,
                                                         timeout=timeout)

        return response if raw else IPSecurityAssociation.from_object_dict(response)
